export class FpsCounter {
    private fpsCounterElement: HTMLDivElement;

    private currentFPS: number;

    private throttledFPS: number;

    private updateFPSCounterRequestAnimationFrameId: number;

    private lastFPSUpdate: number = 0;

    private framesThisSecond: number = 0;

    private updateFPSCounterCallback: (timestamp: number) => void;

    constructor(fpsLimit: number) {
        this.fpsCounterElement = document.createElement('div');
        document.body.appendChild(this.fpsCounterElement);

        this.updateFPSCounterCallback = this.updateFPSCounter.bind(this);

        this.currentFPS = fpsLimit;
        this.throttledFPS = fpsLimit;
        this.show();
    }

    public show(): void {
        this.fpsCounterElement.style.cssText = 'position:absolute;opacity:0.5;z-index:99999999;background:#000;bottom:0;left:0;text-align:center;font-size:1rem;color:#fff;padding:1rem;';

        this.updateFPSOverlayText();

        this.updateFPSCounterRequestAnimationFrameId = window.requestAnimationFrame(this.updateFPSCounterCallback);
    }

    public hide(): void {
        window.cancelAnimationFrame(this.updateFPSCounterRequestAnimationFrameId);

        this.fpsCounterElement.style.cssText = 'opacity:0;';
    }

    private updateFPSOverlayText(): void {
        this.fpsCounterElement.innerText = `FPS: ${this.currentFPS.toFixed(2)} (${this.throttledFPS})`;
    }

    private updateFPSCounter(timestamp: number): void {
        if (timestamp > (this.lastFPSUpdate + 1000)) {
            this.currentFPS = 0.25 * this.framesThisSecond + 0.75 * this.currentFPS;

            this.lastFPSUpdate = timestamp;

            this.framesThisSecond = 0;

            this.updateFPSOverlayText();
        }

        this.framesThisSecond++;

        this.updateFPSCounterRequestAnimationFrameId = window.requestAnimationFrame(this.updateFPSCounterCallback);
    }
}
